-- Stage 11 / Migration 17: audit logs
--
-- * entries are generated by the database (triggers on security-relevant
--   tables) through one service, private.record_audit_event
-- * the actor is ALWAYS derived from the validated session; the service has
--   no actor parameter, so nobody can record an event "as" someone else
-- * append-only: no client or service-role write grants; triggers block
--   UPDATE / DELETE / TRUNCATE for everyone except the explicit retention
--   purge
-- * metadata is minimal and credential-like keys are redacted on insert
-- * readable with audit.view (community events) or by platform admins
--   (system events, no community)

-- ---------------------------------------------------------------------------
-- Action catalog
-- ---------------------------------------------------------------------------
create table public.audit_actions (
  action      text primary key check (action ~ '^[a-z][a-z_]*\.[a-z][a-z_]*$'),
  entity_type text not null,
  description text not null
);

comment on table public.audit_actions is
  'Catalog of audited actions. Only actions with a producer are listed; add new ones together with their producer.';

insert into public.audit_actions (action, entity_type, description) values
  ('community.created',      'community',    'A community was created'),
  ('community.updated',      'community',    'Community details or settings changed'),
  ('membership.created',     'membership',   'A membership was created'),
  ('membership.approved',    'membership',   'A membership was approved or a member re-admitted'),
  ('membership.rejected',    'membership',   'A membership request was rejected'),
  ('membership.suspended',   'membership',   'A member was suspended'),
  ('membership.reinstated',  'membership',   'A suspended member was reinstated'),
  ('membership.left',        'membership',   'A member left the community'),
  ('membership.removed',     'membership',   'A membership was removed'),
  ('role.created',           'role',         'A custom role was created'),
  ('role.updated',           'role',         'A custom role was renamed or edited'),
  ('role.deleted',           'role',         'A custom role was deleted'),
  ('role.assigned',          'membership_role', 'A role was assigned to a member'),
  ('role.unassigned',        'membership_role', 'A role was removed from a member'),
  ('permission.assigned',    'role_permission', 'A permission was granted to a role'),
  ('permission.removed',     'role_permission', 'A permission was revoked from a role'),
  ('post.moderated',         'post',         'A moderator changed a post''s status'),
  ('comment.moderated',      'comment',      'A moderator changed a comment''s status'),
  ('announcement.created',   'announcement', 'An announcement was created'),
  ('announcement.published', 'announcement', 'An announcement was published'),
  ('announcement.deleted',   'announcement', 'An announcement was deleted'),
  ('alert.created',          'alert',        'An alert was created'),
  ('alert.published',        'alert',        'An alert was published'),
  ('alert.cancelled',        'alert',        'An alert was cancelled'),
  ('event.created',          'event',        'An event was created'),
  ('event.cancelled',        'event',        'An event was cancelled'),
  ('document.uploaded',      'document',     'A document upload was completed'),
  ('document.deleted',       'document',     'A document was deleted'),
  ('account.status_changed', 'profile',      'A platform admin changed a user''s account status');

-- ---------------------------------------------------------------------------
-- audit_logs
-- ---------------------------------------------------------------------------
-- No foreign keys on community_id / actor_user_id / entity_id on purpose:
-- audit history must survive the deletion of the community, the account
-- or the entity it describes.
create table public.audit_logs (
  id            uuid primary key default gen_random_uuid(),
  community_id  uuid,
  actor_user_id uuid,
  action        text not null references public.audit_actions (action) on delete restrict,
  entity_type   text not null check (char_length(entity_type) between 1 and 60),
  entity_id     uuid,
  metadata      jsonb not null default '{}'::jsonb
                check (jsonb_typeof(metadata) = 'object' and pg_column_size(metadata) <= 8192),
  -- clock_timestamp: preserves order of several events in one transaction.
  created_at    timestamptz not null default clock_timestamp()
);

comment on table public.audit_logs is
  'Append-only audit trail of security, moderation, administrative and important business actions.';

create index audit_logs_community_created_idx on public.audit_logs (community_id, created_at desc, id desc);
create index audit_logs_system_created_idx on public.audit_logs (created_at desc, id desc) where community_id is null;
create index audit_logs_actor_created_idx on public.audit_logs (actor_user_id, created_at desc);
create index audit_logs_entity_idx on public.audit_logs (entity_type, entity_id);

-- ---------------------------------------------------------------------------
-- Privacy: credential-like keys are redacted wherever they appear
-- ---------------------------------------------------------------------------
create or replace function private.redact_audit_metadata(p_value jsonb)
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  v_result jsonb;
  v_key    text;
  v_val    jsonb;
begin
  if p_value is null then
    return null;
  end if;
  case jsonb_typeof(p_value)
    when 'object' then
      v_result := '{}'::jsonb;
      for v_key, v_val in select * from jsonb_each(p_value) loop
        -- Long markers match anywhere in the key; short ones (pin, otp, ...)
        -- only as whole words so e.g. "shipping" is not redacted.
        if lower(v_key) ~ '(pass(word|wd|phrase)?|secret|token|api[_-]?key|private[_-]?key|access[_-]?key|authorization|auth[_-]?header|cookie|session|credential|card[_-]?number|account[_-]?number)'
           or lower(v_key) ~ '(^|[_-])(otp|pin|card|cvv|cvc|iban|ssn|jwt|bearer)($|[_-])' then
          v_result := v_result || jsonb_build_object(v_key, '[redacted]');
        else
          v_result := v_result || jsonb_build_object(v_key, private.redact_audit_metadata(v_val));
        end if;
      end loop;
      return v_result;
    when 'array' then
      select coalesce(jsonb_agg(private.redact_audit_metadata(e)), '[]'::jsonb) into v_result
      from jsonb_array_elements(p_value) as e;
      return v_result;
    else
      return p_value;
  end case;
end;
$$;

revoke all on function private.redact_audit_metadata(jsonb) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Append-only enforcement
-- ---------------------------------------------------------------------------
create or replace function private.protect_audit_logs()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.metadata := private.redact_audit_metadata(coalesce(new.metadata, '{}'::jsonb));
    new.created_at := clock_timestamp();
    return new;
  end if;
  if tg_op = 'DELETE' and current_setting('communione.audit_purge', true) = 'on' then
    return old;  -- retention purge (private.purge_audit_logs only)
  end if;
  raise exception 'audit logs are append-only (% is not allowed)', tg_op using errcode = '42501';
end;
$$;

revoke all on function private.protect_audit_logs() from public, anon, authenticated;

create trigger audit_logs_protect_rows
  before insert or update or delete on public.audit_logs
  for each row execute function private.protect_audit_logs();

create or replace function private.protect_audit_logs_truncate()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'audit logs are append-only (TRUNCATE is not allowed)' using errcode = '42501';
end;
$$;

revoke all on function private.protect_audit_logs_truncate() from public, anon, authenticated;

create trigger audit_logs_protect_truncate
  before truncate on public.audit_logs
  for each statement execute function private.protect_audit_logs_truncate();

-- ---------------------------------------------------------------------------
-- The audit service
-- ---------------------------------------------------------------------------
-- recordAuditEvent({ communityId, action, entityType, entityId, metadata })
-- The actor is the validated session user for client requests and NULL
-- (system) for trusted server code. There is deliberately no actor
-- parameter.
create or replace function private.record_audit_event(
  p_community_id uuid,
  p_action       text,
  p_entity_type  text,
  p_entity_id    uuid,
  p_metadata     jsonb default '{}'::jsonb
)
returns uuid
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  insert into public.audit_logs (community_id, actor_user_id, action, entity_type, entity_id, metadata)
  values (p_community_id, private.actor_user_id(), p_action, p_entity_type, p_entity_id, coalesce(p_metadata, '{}'::jsonb))
  returning id into v_id;
  return v_id;
end;
$$;

revoke all on function private.record_audit_event(uuid, text, text, uuid, jsonb) from public, anon, authenticated, service_role;

-- Backend entry point for SYSTEM events (actor NULL) only. Service role
-- only; cannot attribute an event to any user.
create or replace function public.record_system_audit_event(
  p_community_id uuid,
  p_action       text,
  p_entity_type  text,
  p_entity_id    uuid default null,
  p_metadata     jsonb default '{}'::jsonb
)
returns uuid
language sql
volatile
security definer
set search_path = ''
as $$
  insert into public.audit_logs (community_id, actor_user_id, action, entity_type, entity_id, metadata)
  values (p_community_id, null, p_action, p_entity_type, p_entity_id, coalesce(p_metadata, '{}'::jsonb))
  returning id;
$$;

revoke all on function public.record_system_audit_event(uuid, text, text, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.record_system_audit_event(uuid, text, text, uuid, jsonb) to service_role;

-- Retention purge: removes entries older than p_older_than. Service role
-- only; the only way rows ever leave the table.
create or replace function public.purge_audit_logs(p_older_than interval)
returns integer
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_count integer;
begin
  if p_older_than < interval '90 days' then
    raise exception 'audit logs must be retained for at least 90 days' using errcode = '22023';
  end if;
  perform set_config('communione.audit_purge', 'on', true);
  delete from public.audit_logs where created_at < now() - p_older_than;
  get diagnostics v_count = row_count;
  perform set_config('communione.audit_purge', 'off', true);
  return v_count;
end;
$$;

revoke all on function public.purge_audit_logs(interval) from public, anon, authenticated;
grant execute on function public.purge_audit_logs(interval) to service_role;

-- ---------------------------------------------------------------------------
-- Privileges and RLS
-- ---------------------------------------------------------------------------
revoke all on table public.audit_logs, public.audit_actions from public, anon, authenticated, service_role;
grant select on table public.audit_logs, public.audit_actions to authenticated, service_role;
alter table public.audit_logs    enable row level security;
alter table public.audit_actions enable row level security;

create policy audit_actions_select_all on public.audit_actions for select to authenticated using (true);

-- Community events: audit.view in that community. System events (no
-- community): platform admins.
create policy audit_logs_select_authorized on public.audit_logs
  for select to authenticated
  using (
    case when community_id is null then (select private.is_platform_admin())
         else public.has_community_permission(community_id, 'audit.view') end
  );

-- Newest first, keyset cursor. p_community_id NULL = system events.
create or replace function public.list_audit_logs(
  p_community_id      uuid,
  p_limit             integer default 50,
  p_cursor_created_at timestamptz default null,
  p_cursor_id         uuid default null,
  p_action            text default null,
  p_actor_user_id     uuid default null,
  p_entity_type       text default null,
  p_entity_id         uuid default null
)
returns setof public.audit_logs
language plpgsql
stable
security invoker
set search_path = ''
as $$
begin
  if (p_cursor_created_at is null) <> (p_cursor_id is null) then
    raise exception 'cursor requires both p_cursor_created_at and p_cursor_id' using errcode = '22023';
  end if;
  return query
  select a.* from public.audit_logs a
  where a.community_id is not distinct from p_community_id
    and (p_action is null or a.action = p_action)
    and (p_actor_user_id is null or a.actor_user_id = p_actor_user_id)
    and (p_entity_type is null or a.entity_type = p_entity_type)
    and (p_entity_id is null or a.entity_id = p_entity_id)
    and (p_cursor_id is null or (a.created_at, a.id) < (p_cursor_created_at, p_cursor_id))
  order by a.created_at desc, a.id desc
  limit least(greatest(coalesce(p_limit, 50), 1), 200);
end;
$$;

revoke all on function public.list_audit_logs(uuid, integer, timestamptz, uuid, text, uuid, text, uuid) from public, anon, authenticated;
grant execute on function public.list_audit_logs(uuid, integer, timestamptz, uuid, text, uuid, text, uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- Producers (AFTER triggers, same transaction as the audited change)
-- ---------------------------------------------------------------------------
-- Metadata holds identifiers, statuses and field NAMES, never content
-- bodies, file contents or personal data beyond ids.

create or replace function private.audit_community()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_changed text[];
begin
  if tg_op = 'INSERT' then
    perform private.record_audit_event(new.id, 'community.created', 'community', new.id,
      jsonb_build_object('slug', new.slug, 'community_type', new.community_type));
  else
    select array_agg(key order by key) into v_changed
    from jsonb_each(to_jsonb(new)) n
    where key not in ('updated_at') and n.value is distinct from (to_jsonb(old) -> key);
    if v_changed is not null then
      perform private.record_audit_event(new.id, 'community.updated', 'community', new.id,
        jsonb_build_object('changed_fields', to_jsonb(v_changed)));
    end if;
  end if;
  return null;
end;
$$;

create trigger communities_audit
  after insert or update on public.communities
  for each row execute function private.audit_community();

create or replace function private.audit_membership()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_action text;
begin
  if tg_op = 'INSERT' then
    perform private.record_audit_event(new.community_id, 'membership.created', 'membership', new.id,
      jsonb_build_object('user_id', new.user_id, 'status', new.status));
  elsif tg_op = 'DELETE' then
    perform private.record_audit_event(old.community_id, 'membership.removed', 'membership', old.id,
      jsonb_build_object('user_id', old.user_id, 'previous_status', old.status));
  elsif new.status is distinct from old.status then
    v_action := case
      when new.status = 'active' and old.status = 'suspended' then 'membership.reinstated'
      when new.status = 'active' then 'membership.approved'
      when new.status = 'suspended' then 'membership.suspended'
      when new.status = 'rejected' then 'membership.rejected'
      when new.status = 'left' then 'membership.left'
    end;
    if v_action is not null then
      perform private.record_audit_event(new.community_id, v_action, 'membership', new.id,
        jsonb_build_object('user_id', new.user_id, 'from', old.status, 'to', new.status));
    end if;
  end if;
  return null;
end;
$$;

create trigger memberships_audit
  after insert or update of status or delete on public.memberships
  for each row execute function private.audit_membership();

-- Custom roles only: system roles are created (with their permissions) by
-- create_community and are immutable, so logging them would only be noise.
create or replace function private.audit_role()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' and not new.is_system_role then
    perform private.record_audit_event(new.community_id, 'role.created', 'role', new.id, jsonb_build_object('name', new.name));
  elsif tg_op = 'UPDATE' and not new.is_system_role and (new.name, new.description) is distinct from (old.name, old.description) then
    perform private.record_audit_event(new.community_id, 'role.updated', 'role', new.id,
      jsonb_build_object('name', new.name, 'previous_name', old.name));
  elsif tg_op = 'DELETE' and not old.is_system_role then
    perform private.record_audit_event(old.community_id, 'role.deleted', 'role', old.id, jsonb_build_object('name', old.name));
  end if;
  return null;
end;
$$;

create trigger roles_audit
  after insert or update or delete on public.roles
  for each row execute function private.audit_role();

create or replace function private.audit_membership_role()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.membership_roles := case when tg_op = 'DELETE' then old else new end;
  v_user uuid;
  v_role text;
begin
  select m.user_id into v_user from public.memberships m where m.id = v_row.membership_id;
  select r.name into v_role from public.roles r where r.id = v_row.role_id;
  perform private.record_audit_event(
    v_row.community_id,
    case when tg_op = 'DELETE' then 'role.unassigned' else 'role.assigned' end,
    'membership_role', v_row.id,
    jsonb_build_object('membership_id', v_row.membership_id, 'user_id', v_user, 'role_id', v_row.role_id, 'role_name', v_role));
  return null;
end;
$$;

create trigger membership_roles_audit
  after insert or delete on public.membership_roles
  for each row execute function private.audit_membership_role();

-- Permission grants on custom roles. Skipped for system roles (only ever
-- set at community creation) and for cascades of a deleted role (the
-- role.deleted entry covers them).
create or replace function private.audit_role_permission()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row       public.role_permissions := case when tg_op = 'DELETE' then old else new end;
  v_community uuid;
  v_system    boolean;
  v_key       text;
begin
  select r.community_id, r.is_system_role into v_community, v_system from public.roles r where r.id = v_row.role_id;
  if v_community is null or v_system then
    return null;
  end if;
  select p.key into v_key from public.permissions p where p.id = v_row.permission_id;
  perform private.record_audit_event(
    v_community,
    case when tg_op = 'DELETE' then 'permission.removed' else 'permission.assigned' end,
    'role_permission', v_row.role_id,
    jsonb_build_object('role_id', v_row.role_id, 'permission', v_key));
  return null;
end;
$$;

create trigger role_permissions_audit
  after insert or delete on public.role_permissions
  for each row execute function private.audit_role_permission();

-- Moderation: status changes made by someone other than the author.
create or replace function private.audit_content_moderation()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status is distinct from old.status
     and new.author_user_id is distinct from private.actor_user_id() then
    perform private.record_audit_event(new.community_id,
      case tg_table_name when 'posts' then 'post.moderated' else 'comment.moderated' end,
      case tg_table_name when 'posts' then 'post' else 'comment' end,
      new.id,
      jsonb_build_object('author_user_id', new.author_user_id, 'from', old.status, 'to', new.status,
                         'reason', new.moderation_reason));
  end if;
  return null;
end;
$$;

create trigger posts_audit_moderation
  after update of status on public.posts
  for each row execute function private.audit_content_moderation();

create trigger comments_audit_moderation
  after update of status on public.comments
  for each row execute function private.audit_content_moderation();

create or replace function private.audit_announcement()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    perform private.record_audit_event(new.community_id, 'announcement.created', 'announcement', new.id,
      jsonb_build_object('status', new.status, 'priority', new.priority));
  end if;
  if new.status = 'published' and (tg_op = 'INSERT' or old.status <> 'published') then
    perform private.record_audit_event(new.community_id, 'announcement.published', 'announcement', new.id,
      jsonb_build_object('priority', new.priority));
  elsif tg_op = 'UPDATE' and new.status = 'deleted' and old.status <> 'deleted' then
    perform private.record_audit_event(new.community_id, 'announcement.deleted', 'announcement', new.id,
      jsonb_build_object('previous_status', old.status));
  end if;
  return null;
end;
$$;

create trigger announcements_audit
  after insert or update of status on public.announcements
  for each row execute function private.audit_announcement();

create or replace function private.audit_alert()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    perform private.record_audit_event(new.community_id, 'alert.created', 'alert', new.id,
      jsonb_build_object('severity', new.severity, 'status', new.status));
  end if;
  if new.status = 'published' and (tg_op = 'INSERT' or old.status <> 'published') then
    perform private.record_audit_event(new.community_id, 'alert.published', 'alert', new.id,
      jsonb_build_object('severity', new.severity));
  elsif tg_op = 'UPDATE' and new.status = 'cancelled' and old.status <> 'cancelled' then
    perform private.record_audit_event(new.community_id, 'alert.cancelled', 'alert', new.id,
      jsonb_build_object('severity', new.severity, 'previous_status', old.status, 'reason', new.cancellation_reason));
  end if;
  return null;
end;
$$;

create trigger alerts_audit
  after insert or update of status on public.alerts
  for each row execute function private.audit_alert();

create or replace function private.audit_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    perform private.record_audit_event(new.community_id, 'event.created', 'event', new.id,
      jsonb_build_object('status', new.status, 'starts_at', new.starts_at, 'capacity', new.capacity));
  elsif new.status = 'cancelled' and old.status <> 'cancelled' then
    perform private.record_audit_event(new.community_id, 'event.cancelled', 'event', new.id,
      jsonb_build_object('previous_status', old.status, 'reason', new.cancellation_reason));
  end if;
  return null;
end;
$$;

create trigger events_audit
  after insert or update of status on public.events
  for each row execute function private.audit_event();

create or replace function private.audit_document()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status = 'active' and old.status = 'pending_upload' then
    perform private.record_audit_event(new.community_id, 'document.uploaded', 'document', new.id,
      jsonb_build_object('uploaded_by', new.uploaded_by, 'mime_type', new.mime_type,
                         'file_size', new.file_size, 'visibility', new.visibility));
  elsif new.status = 'deleted' and old.status <> 'deleted' then
    perform private.record_audit_event(new.community_id, 'document.deleted', 'document', new.id,
      jsonb_build_object('uploaded_by', new.uploaded_by, 'previous_status', old.status));
  end if;
  return null;
end;
$$;

create trigger documents_audit
  after update of status on public.documents
  for each row execute function private.audit_document();

-- Platform-level: account status changes (system event, no community).
create or replace function private.audit_account_status()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status is distinct from old.status then
    perform private.record_audit_event(null, 'account.status_changed', 'profile', new.id,
      jsonb_build_object('from', old.status, 'to', new.status));
  end if;
  return null;
end;
$$;

create trigger profiles_audit_status
  after update of status on public.profiles
  for each row execute function private.audit_account_status();

revoke all on function private.audit_community()          from public, anon, authenticated;
revoke all on function private.audit_membership()         from public, anon, authenticated;
revoke all on function private.audit_role()               from public, anon, authenticated;
revoke all on function private.audit_membership_role()    from public, anon, authenticated;
revoke all on function private.audit_role_permission()    from public, anon, authenticated;
revoke all on function private.audit_content_moderation() from public, anon, authenticated;
revoke all on function private.audit_announcement()       from public, anon, authenticated;
revoke all on function private.audit_alert()              from public, anon, authenticated;
